import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 10
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')

    parsed_rows = []
    for row in reader:
        if not row or all(value == "" for value in row):
            continue
        parsed_rows.append([value for value in row])

    # Ignore leading one-field preamble lines when a consistently sized table
    # follows them.
    start = 0
    for index, row in enumerate(parsed_rows):
        if len(row) >= expected_width:
            start = index
            break
    rows = parsed_rows[start:]

    if not rows:
        return {
            "columns": [f"column_{index + 1}" for index in range(expected_width)],
            "rows": [],
        }

    width = max(expected_width, max(len(row) for row in rows))

    def looks_like_header(row: list[str]) -> bool:
        if len(row) != width:
            return False
        return any(re.search(r"[A-Za-z]", value) for value in row)

    if looks_like_header(rows[0]):
        columns = rows[0][:]
        data_rows = rows[1:]
        if len(columns) < width:
            columns.extend(f"column_{index + 1}" for index in range(len(columns), width))
    else:
        columns = [f"column_{index + 1}" for index in range(width)]
        data_rows = rows

    normalized_rows = []
    for row in data_rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        normalized_rows.append(row)

    return {"columns": columns, "rows": normalized_rows}
